// Pages deployment target for the mirror docs site. Generated by
// scripts/gen-mirror-docs.mjs — do not edit by hand. Environment variables
// still take priority so a one-off build can retarget any host.
const rawBase = process.env.WIQD_DOCS_BASE || '/wiqd/';
const normalizedBase = `/${rawBase.replace(/^\/+|\/+$/g, '')}/`.replace(/\/{2,}/g, '/');

export const site = process.env.WIQD_DOCS_SITE || 'https://microsoft.github.io';
export const base = normalizedBase;

// Baked at mirror-generation time from the repo-root VERSION; the mirror tree
// has no VERSION file to read.
export const version = '0.13.0';

// Preview status tracks pre-1.0 (major 0); mirror has no VERSION file.
export function isPreviewVersion(v) {
  return Number(String(v).split('.')[0]) === 0;
}

export const isPreview = isPreviewVersion(version);
